import { useEffect, useMemo, useRef, useState } from 'react'
import { createPortal } from 'react-dom'
import { MapContainer, Marker, Polygon, Popup, useMap } from 'react-leaflet'
import L from 'leaflet'
import { useMapTheme } from '@features/map-theme/useMapTheme'
import MapTiles, { MapThemeToggle, useInjectMapThemeStyle } from '@features/map-theme/MapTiles'
import { MAP_UI } from '@features/map-theme/map-theme'
import { isPlatformZone, visibleZones } from '@features/gps-lvn/zone-source'
import 'leaflet/dist/leaflet.css'
import type { GpsLiveDevice, GpsMapGeofence, GpsMapLandmark } from '@sdk/gps-lvn.sdk'
import { landmarkDivIcon } from './LandmarkIcon'
const colors = { moving: '#16a34a', idle: '#2563eb', parked: '#eab308', unknown: '#64748b' }
const landmarkLabels: Record<GpsMapLandmark['category'], string> = {
  landmark: 'معلم عام',
  garage: 'كراج',
  station: 'محطة',
  maintenance: 'صيانة',
  office: 'مقر إداري',
  checkpoint: 'نقطة سيطرة',
  hazard: 'موقع خطورة',
  other: 'أخرى',
}
const labels = {
  moving: 'متحركة',
  idle: 'متوقفة والمحرك يعمل',
  parked: 'متوقفة والمحرك مطفأ',
  unknown: 'غير معروفة',
}
/**
 * 00212 — إطار الخريطة الافتراضي:
 *  1) الزونات أولاً (منطقة العمل الفعلية)، 2) وإلا الآليات/المعالم داخل نطاق العراق فقط.
 *  إحداثيات شاذة (0,0 أو خارج العراق — أجهزة بلا إشارة GPS) كانت توسّع الإطار ليشمل أفريقيا كلها.
 *  3) آخر إطار يختاره المستخدم يُحفظ في sessionStorage ويُستعاد بعد تحديث الصفحة.
 */
const IRAQ = { minLat: 28.5, maxLat: 38.0, minLng: 38.0, maxLng: 49.5 }
export const isPlausiblePoint = (lat: number, lng: number) =>
  Number.isFinite(lat) && Number.isFinite(lng) && !(Math.abs(lat) < 0.01 && Math.abs(lng) < 0.01) &&
  lat >= IRAQ.minLat && lat <= IRAQ.maxLat && lng >= IRAQ.minLng && lng <= IRAQ.maxLng
const zonePoint = (pt: GpsMapGeofence['polygon'][number]): [number, number] =>
  Array.isArray(pt) ? [pt[0], pt[1]] : [pt.lat, pt.lng]
export function collectPoints(rows: GpsLiveDevice[], landmarks: GpsMapLandmark[], zones: GpsMapGeofence[] = []) {
  const zonePts = zones.flatMap((z) => (z.polygon ?? []).map(zonePoint)).filter(([a, b]) => isPlausiblePoint(a, b))
  if (zonePts.length) return zonePts
  return [
    ...rows.map((row) => [row.latitude, row.longitude] as [number, number]),
    ...landmarks.map((landmark) => [landmark.latitude, landmark.longitude] as [number, number]),
  ].filter(([a, b]) => isPlausiblePoint(a, b))
}
const VIEW_KEY = 'gps-live-map:view'
type SavedView = { lat: number; lng: number; zoom: number }
export const readSavedView = (): SavedView | null => {
  try {
    const raw = sessionStorage.getItem(VIEW_KEY)
    if (!raw) return null
    const v = JSON.parse(raw) as SavedView
    return isPlausiblePoint(v.lat, v.lng) && Number.isFinite(v.zoom) ? v : null
  } catch {
    return null
  }
}
// ملاءمة الإطار مرة واحدة فقط عند أول وصول للبيانات — تحدّثات المزامنة
// اللاحقة لا تحرّك الشاشة؛ المستخدم يستعيدها يدوياً بزر «ملاءمة العرض».
function Fit({
  rows,
  landmarks,
  zones,
  fitSignal,
}: {
  rows: GpsLiveDevice[]
  landmarks: GpsMapLandmark[]
  zones: GpsMapGeofence[]
  fitSignal: number
}) {
  const map = useMap()
  const dataRef = useRef({ rows, landmarks, zones })
  dataRef.current = { rows, landmarks, zones }
  const fittedOnce = useRef(Boolean(readSavedView()))   // إطار محفوظ من قبل ⇒ لا ملاءمة تلقائية
  const fittedWithZones = useRef(false)
  const firstFitAt = useRef(0)
  useEffect(() => {
    const hasZones = zones.some((z) => (z.polygon ?? []).length > 0)
    // الآليات تصل قبل الزونات أحياناً: نسمح بملاءمة ثانية واحدة عند وصول الزونات خلال 15 ثانية من الأولى
    const zoneRefit = fittedOnce.current && hasZones && !fittedWithZones.current && firstFitAt.current > 0 && Date.now() - firstFitAt.current < 15_000
    if (fittedOnce.current && !zoneRefit) return
    const points = collectPoints(rows, landmarks, zones)
    if (!points.length) return
    if (!fittedOnce.current) firstFitAt.current = Date.now()
    fittedOnce.current = true
    if (hasZones) fittedWithZones.current = true
    map.fitBounds(L.latLngBounds(points), {
      padding: [30, 30],
      maxZoom: 16,
    })
  }, [landmarks, map, rows, zones])
  // زر الملاءمة فقط — تحديثات المزامنة لا تحرّك الخريطة أبداً
  useEffect(() => {
    if (!fitSignal) return
    const points = collectPoints(dataRef.current.rows, dataRef.current.landmarks, dataRef.current.zones)
    if (points.length)
      map.fitBounds(L.latLngBounds(points), {
        padding: [30, 30],
        maxZoom: 16,
      })
  }, [fitSignal, map])
  // حفظ الإطار الحالي عند كل تحريك/تكبير من المستخدم
  useEffect(() => {
    const save = () => {
      const c = map.getCenter()
      try {
        sessionStorage.setItem(VIEW_KEY, JSON.stringify({ lat: c.lat, lng: c.lng, zoom: map.getZoom() }))
      } catch {
        /* تخزين غير متاح */
      }
    }
    map.on('moveend', save)
    return () => {
      map.off('moveend', save)
    }
  }, [map])
  return null
}
function InvalidateSize({ dep }: { dep: unknown }) {
  const map = useMap()
  useEffect(() => {
    map.invalidateSize()
  }, [dep, map])
  return null
}
// ذاكرة أيقونات: نفس الأيقونة لكل (لون/اتجاه مقرّب/حجم) — لا إعادة إنشاء
// كل مزامنة (يمنع الوميض ويثبّت الرسم)
// 00388-ج: توهّج المركبات — هالة نابضة للمتحركة، توهّج ساكن للمتوقفة؛ أقوى في الوضع الليلي
const GPS_CSS_ID = 'gps-live-map-style'
const GPS_CSS = `
.gps-arrow { position: relative; width: 100%; height: 100%; line-height: 0; }
.gps-arrow__halo { position: absolute; inset: 15%; border-radius: 9999px; background: var(--c); opacity: .25; filter: blur(3px); }
.gps-arrow--moving .gps-arrow__halo { animation: gps-pulse 1.8s ease-out infinite; }
.gps-arrow__svg { position: relative; filter: drop-shadow(0 1px 2px rgba(0,0,0,.45)); }
.akaram-map-dark .gps-arrow__svg { filter: drop-shadow(0 0 4px var(--c)) drop-shadow(0 0 1px rgba(0,0,0,.9)); }
.akaram-map-dark .gps-arrow__halo { opacity: .45; filter: blur(4px); }
@keyframes gps-pulse { 0% { transform: scale(.7); opacity: .55; } 100% { transform: scale(1.9); opacity: 0; } }
@media (prefers-reduced-motion: reduce) { .gps-arrow--moving .gps-arrow__halo { animation: none; } }
`
function useInjectGpsStyle() {
  useEffect(() => {
    if (document.getElementById(GPS_CSS_ID)) return
    const el = document.createElement('style'); el.id = GPS_CSS_ID; el.textContent = GPS_CSS; document.head.appendChild(el)
  }, [])
}
const iconCache = new Map<string, L.DivIcon>()
export const arrowIcon = (color: string, course: number | null, active: boolean, moving = false) => {
  const deg = (Math.round((course ?? 0) / 10) * 10) % 360
  const key = `${color}|${deg}|${active}|${moving}`
  const cached = iconCache.get(key)
  if (cached) return cached
  const size = active ? 30 : 24
  const icon = L.divIcon({
    className: 'gps-arrow-icon',
    html: `<div class="gps-arrow${moving ? ' gps-arrow--moving' : ''}" data-moving="${moving}" style="--c:${color};width:${size}px;height:${size}px"><span class="gps-arrow__halo"></span><svg class="gps-arrow__svg" width="${size}" height="${size}" viewBox="0 0 24 24" style="transform:rotate(${deg}deg)"><path d="M12 1.5 L19.5 21 L12 16 L4.5 21 Z" fill="${color}" stroke="#ffffff" stroke-width="1.6" stroke-linejoin="round"/></svg></div>`,
    iconSize: [size, size],
    iconAnchor: [size / 2, size / 2],
    popupAnchor: [0, -size / 2],
  })
  iconCache.set(key, icon)
  return icon
}
export default function GpsLiveMap({
  rows,
  zones,
  landmarks,
}: {
  rows: GpsLiveDevice[]
  zones: GpsMapGeofence[]
  landmarks: GpsMapLandmark[]
}) {
  useInjectMapThemeStyle(); useInjectGpsStyle()
  const [theme, , toggleTheme] = useMapTheme('light')
  const ui = MAP_UI[theme]
  const [tileFailed, setTileFailed] = useState(false)
  const [saved] = useState(readSavedView)   // 00212: استعادة آخر إطار بعد تحديث الصفحة
  const [fitSignal, setFitSignal] = useState(0)
  const [full, setFull] = useState(false)
  const [layers, setLayers] = useState({ vehicles: true, zones: true, landmarks: true })   // 00386-أ: طبقة بقع التوقف القديمة أُزيلت (الخلف: وحدة خريطة النفايات)
  // 00410: زونات المزوّد (LVN) مخفية افتراضياً — تتداخل حدودها مع قواطع المنصة
  const [showProviderZones, setShowProviderZones] = useState(false)
  const drawnZones = useMemo(() => visibleZones(zones, showProviderZones), [zones, showProviderZones])
  const platformZoneCount = useMemo(() => zones.filter(isPlatformZone).length, [zones])
  const providerZoneCount = zones.length - platformZoneCount
  const toggleLayer = (key: keyof typeof layers) =>
    setLayers((current) => ({ ...current, [key]: !current[key] }))
  // 00362 — طبقة بقع التوقف: تُحمَّل فقط عند تشغيلها، وتتحدّث كل دقيقة
  // ملء الشاشة عبر portal إلى body — يهرب من أي ancestor بـ transform/filter
  // كان يكسر position:fixed ويجعل الخريطة لا تملأ النافذة
  const shell = (
    <div className={full ? `fixed inset-0 z-[2000] ${ui.container}` : `relative overflow-hidden rounded-2xl border ${ui.container}`} data-testid="gps-live-map" data-map-theme={theme}>
      <div className={`absolute right-3 top-3 z-[1000] max-w-[calc(100%-1.5rem)] rounded-2xl border p-2 shadow-xl ${ui.panel}`}>
        <div className="flex flex-wrap gap-1.5 text-[10px] font-black">
          <MapThemeToggle theme={theme} onToggle={toggleTheme} testId="gps-live-map-theme" />
          <button
            type="button"
            aria-pressed={layers.vehicles}
            onClick={() => toggleLayer('vehicles')}
            className={`rounded-xl px-3 py-2 transition ${layers.vehicles ? 'bg-slate-950 text-white' : ui.chip}`}
          >
            ● الآليات ({rows.length})
          </button>
          <button
            type="button"
            aria-pressed={layers.zones}
            onClick={() => toggleLayer('zones')}
            className={`rounded-xl px-3 py-2 transition ${layers.zones ? 'bg-violet-700 text-white' : ui.chip}`}
          >
            ▧ زونات المنصة ({platformZoneCount})
          </button>
          {/* 00410: زونات المزوّد تُعرض فقط عند الطلب — تتداخل حدودها مع قواطع المنصة */}
          <button
            type="button"
            data-testid="gps-live-map-provider-zones"
            aria-pressed={showProviderZones}
            disabled={!providerZoneCount}
            onClick={() => setShowProviderZones((value) => !value)}
            title="حدود مزوّد GPS المستوردة — للمراجعة فقط، تُخفيها افتراضياً لأنها تتداخل مع قواطع المنصة"
            className={`rounded-xl px-3 py-2 transition disabled:opacity-40 ${showProviderZones ? 'bg-blue-700 text-white' : ui.chip}`}
          >
            {showProviderZones ? 'إخفاء زونات المزوّد' : `إظهار زونات المزوّد (${providerZoneCount})`}
          </button>
          <button
            type="button"
            aria-pressed={layers.landmarks}
            onClick={() => toggleLayer('landmarks')}
            className={`rounded-xl px-3 py-2 transition ${layers.landmarks ? 'bg-orange-600 text-white' : ui.chip}`}
          >
            ◆ المعالم ({landmarks.length})
          </button>
          <button
            type="button"
            onClick={() => setFitSignal((value) => value + 1)}
            title="إعادة توسيط الخريطة على كل الآليات والمعالم"
            className="rounded-xl bg-cyan-700 px-3 py-2 text-white transition hover:bg-cyan-800"
          >
            ⛶ ملاءمة العرض
          </button>
          <button
            type="button"
            aria-pressed={full}
            onClick={() => setFull((value) => !value)}
            className="rounded-xl bg-slate-950 px-3 py-2 text-white transition hover:bg-slate-800"
          >
            {full ? '✕ إنهاء ملء الشاشة' : '⛶ ملء الشاشة'}
          </button>
        </div>
        {layers.vehicles && (
          <div className={`mt-2 flex flex-wrap gap-2 border-t pt-2 text-[9px] font-bold ${theme === 'dark' ? 'border-white/15' : ''}`}>
            {(Object.keys(labels) as (keyof typeof labels)[]).map((k) => (
              <span key={k} className="flex items-center gap-1"><span className="size-2.5 rounded-full" style={{ background: colors[k], boxShadow: theme === 'dark' ? `0 0 6px ${colors[k]}` : undefined }} />{k === 'idle' ? 'محرك يعمل' : k === 'parked' ? 'محرك مطفأ' : labels[k]}</span>
            ))}
          </div>
        )}
      </div>
      {tileFailed && (
        <div className="absolute inset-x-16 bottom-3 z-[1000] rounded-xl bg-amber-50 p-2 text-center text-xs font-bold text-amber-900">
          تعذر تحميل خلفية الخريطة؛ تحقق من الاتصال ثم أعد تحميل الصفحة.
        </div>
      )}
      <MapContainer
        center={saved ? [saved.lat, saved.lng] : [33.3152, 44.3661]}
        zoom={saved?.zoom ?? 11}
        className={full ? 'h-full w-full' : 'h-[65vh] min-h-[460px] w-full'}
      >
        <MapTiles theme={theme} onFailed={setTileFailed} preferOsmDark />
        {layers.zones &&
          drawnZones.map((zone) => {
            const positions = zone.polygon.map((p) =>
              Array.isArray(p) ? p : ([p.lat, p.lng] as [number, number]),
            )
            return (
              <Polygon
                key={zone.id}
                positions={positions}
                pathOptions={{ color: zone.color || '#7c3aed', fillOpacity: 0.08, weight: 2 }}
              >
                <Popup>
                  <b>{zone.name}</b>
                  <br />
                  {zone.source === 'lvn' ? 'منطقة مستوردة من LVN' : 'منطقة المنصة'}
                </Popup>
              </Polygon>
            )
          })}
        {layers.landmarks &&
          landmarks.map((landmark) => (
            <Marker
              key={`landmark-${landmark.id}`}
              position={[landmark.latitude, landmark.longitude]}
              icon={landmarkDivIcon(landmark.icon ?? 'pin', landmark.color)}
            >
              <Popup>
                <b>{landmark.name}</b>
                <br />
                معلم تشغيلي · {landmarkLabels[landmark.category]}
                {landmark.notes ? (
                  <>
                    <br />
                    {landmark.notes}
                  </>
                ) : null}
              </Popup>
            </Marker>
          ))}
        {layers.vehicles &&
          rows.map((row) => (
            <Marker
              key={row.device_id}
              position={[row.latitude, row.longitude]}
              icon={arrowIcon(
                colors[row.operational_status],
                row.course,
                Boolean(row.departure_id),
                row.operational_status === 'moving',
              )}
            >
              <Popup>
                <b>{row.vehicle_name ?? row.device_name}</b>
                <br />
                {row.db_number ? `DB ${row.db_number}` : `LVN ${row.external_id}`}
                <br />
                {labels[row.operational_status]} · {row.speed ?? 0} كم/س
                <br />
                {row.driver_name ?? 'السائق غير محدد'}
                <br />
                {row.address ?? 'العنوان غير متوفر'}
                <br />
                {row.departure_id ? 'ضمن انطلاقة حالية' : 'لا توجد انطلاقة'}
                <br />
                {row.assigned_zone_count === 0
                  ? 'لا يوجد زون مخصص'
                  : row.inside_assigned_zone
                    ? 'داخل الزون'
                    : 'خارج الزون'}
              </Popup>
            </Marker>
          ))}
        {/* 00410: الملاءمة على زونات المنصة — حدود المزوّد لا توسّع الإطار */}
        <Fit rows={rows} landmarks={landmarks} zones={drawnZones} fitSignal={fitSignal} />
        <InvalidateSize dep={full} />
      </MapContainer>
    </div>
  )
  return full ? createPortal(shell, document.body) : shell
}
